<template><view class="onboarding-page ld-page"><view class="onboarding-hero"><view class="hero-icon"><PrototypeIcon name="people" tone="white" :size="48"/></view><view><text class="hero-title">{{choose?'组织切换':'我的组织'}}</text><text class="hero-caption">{{choose?'切换空间，继续你的陪伴':'开启属于你的成长陪伴空间'}}</text></view><button class="hero-tool" @tap="settings"><PrototypeIcon name="user" tone="white" :size="36"/></button></view>
 <view class="onboarding-content"><view v-if="loading" class="loading-state">正在加载…</view><view v-if="error" class="error-card"><text>{{error}}</text><button @tap="load">重试</button></view><template v-if="ready">
 <view class="section-title"><text>我的组织</text><text class="section-count">{{organizations.length}} 个</text></view><view class="white-group"><view v-if="!organizations.length" class="empty-card"><PrototypeIcon name="growth" :size="64"/><text>还没有加入组织</text><text class="muted">创建家庭，或申请学校、培训机构入驻</text></view><view v-for="org in organizations" :key="org.id" class="organization-row"><view :class="['organization-icon',{family:org.typeCode==='FAMILY'}]"><PrototypeIcon :name="org.typeCode==='FAMILY'?'home':'school'" :size="42"/></view><view class="row-copy"><text class="row-title">{{org.name}}</text><view class="row-tags"><text>{{org.typeCode==='FAMILY'?'家庭':org.typeCode==='SCHOOL'?'学校':'培训机构'}}</text><text>{{org.owner?'负责人':org.roleCodes.some(x=>['PARENT_ADMIN','ORG_ADMIN','ORGADMIN'].includes(x))?'管理员':'组织成员'}}</text></view></view><button v-if="org.canEnterFamily||org.canEnterInstitution" class="outline-small" :disabled="busy" @tap="enter(org)">进入</button></view></view>
 <view class="join-actions"><button @tap="create('family')"><PrototypeIcon name="home" :size="42"/><text>创建家庭</text><PrototypeIcon name="arrow" :size="24"/></button><button @tap="create('institution')"><PrototypeIcon name="school" :size="42"/><text>学校 / 培训机构入驻</text><PrototypeIcon name="arrow" :size="24"/></button></view>
 <button v-if="identity==='parent'" class="invitation-action" @tap="joinInvitation"><PrototypeIcon name="people" :size="32"/><text>接受陪伴关系邀请</text><PrototypeIcon name="arrow" :size="24"/></button>
 <view class="section-title"><text>我的申请</text><text class="section-count">{{applications.length}} 项</text></view><view class="white-group"><view v-if="!applications.length" class="quiet-empty">暂无入驻申请</view><view v-for="item in applications" :key="item.id" class="application-row" @tap="detail(item.id)"><view class="organization-icon"><PrototypeIcon name="school" :size="42"/></view><view class="row-copy"><text class="row-title">{{item.name}}</text><text class="row-caption">{{item.createdAt.replace('T',' ').slice(0,16)}}</text></view><text :class="['status-tag','status-'+item.status.toLowerCase()]">{{applicationStatus[item.status]}}</text><PrototypeIcon name="arrow" tone="muted" :size="24"/></view></view>
 </template></view></view></template>
<script setup lang="ts">
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import {ref} from 'vue';
import {getParentState} from '@/api/auth';
import {ApiError} from '@/api/http';
import {onLoad,onShow} from '@dcloudio/uni-app';
import {onboardingApi,applicationStatus,type MyOrganization,type OrganizationApplication} from '@/api/organization-onboarding';
import {onboardingIdentity,resolveOnboardingSession,onboardingUrl,type OnboardingIdentity} from '@/session/onboarding-session';
import {getParentSession,saveParentSession} from '@/session/parent-session';
import {getOrganizationSession,saveOrganizationSession} from '@/session/organization-session';
const choose=ref(false);
const identity=ref<OnboardingIdentity|null>(null),organizations=ref<MyOrganization[]>([]),applications=ref<OrganizationApplication[]>([]),loading=ref(true),ready=ref(false),busy=ref(false),error=ref('');
onLoad(options=>{identity.value=onboardingIdentity(options?.identity);choose.value=options?.choose==='1';});onShow(load);
async function load(){const session=await resolveOnboardingSession(identity.value);if(!session){loading.value=false;error.value='请从当前账号的入驻进度入口进入';return;}loading.value=true;ready.value=false;error.value='';try{const context=await onboardingApi.context(session.accessToken);[organizations.value,applications.value]=await Promise.all([onboardingApi.organizations(session.accessToken),onboardingApi.applications(session.accessToken)]);ready.value=true;const previous=uni.getStorageSync('lingdong.selected-organization') as {userId?:string;organizationId?:string}|undefined;const accessible=(previous?.userId===context.userId?organizations.value.find(x=>x.id===previous.organizationId&&(x.canEnterFamily||x.canEnterInstitution)):undefined)??organizations.value.find(x=>x.canEnterFamily||x.canEnterInstitution);if(accessible&&!choose.value)await enter(accessible);}catch(e){error.value=e instanceof Error?e.message:'加载失败';}finally{loading.value=false;}}
function settings(){if(identity.value)uni.navigateTo({url:'/pages/account-settings/account-settings?identity='+identity.value});}
function create(kind:string){if(identity.value)uni.navigateTo({url:onboardingUrl('organization-onboarding',identity.value,`&kind=${kind}`)});}
function detail(id:string){if(identity.value)uni.navigateTo({url:onboardingUrl('organization-application',identity.value,`&id=${encodeURIComponent(id)}`)});}
async function joinInvitation(){const result=await uni.showModal({title:'接受家长关系邀请',editable:true,placeholderText:'请输入邀请链接中的 invitationId'});if(result.confirm && result.content?.trim())uni.navigateTo({url:'/pages/parent-relationship-invitation/parent-relationship-invitation?invitationId='+encodeURIComponent(result.content.trim())});}
async function enter(org:MyOrganization){const session=await resolveOnboardingSession(identity.value);if(!session||busy.value)return;busy.value=true;error.value='';try{const [context,rows]=await Promise.all([onboardingApi.context(session.accessToken),onboardingApi.organizations(session.accessToken)]);const current=rows.find(x=>x.id===org.id);if(!current||(!current.canEnterFamily&&!current.canEnterInstitution))throw new Error('当前组织已不可进入，请刷新');const target=current.canEnterFamily?getParentSession():getOrganizationSession();if(target&&target.accessToken!==session.accessToken){try{const other=await onboardingApi.context(target.accessToken);if(other.userId!==context.userId)throw new Error('目标身份已登录其他账号，请先退出该账号');}catch(e){if(!(e instanceof ApiError)||e.statusCode!==401)throw e;const key=current.canEnterFamily?'lingdong.parent.session':'lingdong.organization.session';const stored=uni.getStorageSync(key);if(stored?.accessToken===target.accessToken)uni.removeStorageSync(key);}}if(current.canEnterFamily)saveParentSession(session,context.mobile||'');else saveOrganizationSession(session);uni.setStorageSync('lingdong.selected-organization',{userId:context.userId,organizationId:current.id,name:current.name,typeCode:current.typeCode,accessToken:session.accessToken});let destination=current.canEnterFamily?'/pages/parent-home/parent-home':'/pages/organization-home/organization-home';if(current.canEnterFamily){const state=await getParentState(session.accessToken);if(state.onboardingRequired||state.agreementAcceptanceRequired)destination='/pages/parent-onboarding/parent-onboarding';}await uni.reLaunch({url:destination});}catch(e){error.value=e instanceof Error?e.message:'进入失败';}finally{busy.value=false;}}
</script>
<style lang="scss" scoped>
@import '@/styles/onboarding-prototype.scss';
.onboarding-page{background:#f5f9f3;padding-bottom:55rpx;}.onboarding-hero{background:transparent;color:#183d2d;min-height:100rpx;padding:24rpx 30rpx;margin:0;box-shadow:none;border-radius:0;justify-content:center;}.hero-icon,.hero-caption{display:none;}.hero-title{font-size:34rpx;color:#183d2d;}.hero-tool{position:absolute;right:28rpx;background:#176c51;border-radius:50%;}.onboarding-content{padding:20rpx 28rpx;}.white-group{background:#fff;border:0;border-radius:26rpx;box-shadow:none;margin-bottom:24rpx;}.form-group{padding:28rpx;}.form-section{font-size:28rpx;margin-bottom:22rpx;}.form-label{font-size:26rpx;margin:22rpx 0 12rpx;}.form-group input,.picker-row{background:#fafcfb;border:1rpx solid #e0e8e2;border-radius:16rpx;min-height:82rpx;padding:16rpx 20rpx;font-size:26rpx;box-sizing:border-box;}.primary-action{background:linear-gradient(110deg,#176b53,#0a5b40);border-radius:18rpx;font-size:30rpx;}.outline-action,.outline-small{border:1rpx solid #247b5b;color:#1a6c50;border-radius:16rpx;}.organization-row,.application-row{padding:24rpx;gap:20rpx;}.organization-icon{background:#e9f5ed;border-radius:16rpx;}.row-title{font-size:28rpx;}.row-caption{font-size:23rpx;}.row-tags text{background:#e8f2ec;color:#32705b;}.step-track{margin:0 0 28rpx;font-size:23rpx;}.timeline-card{padding:30rpx;}.timeline-step{padding:20rpx 0;}.timeline-dot{width:42rpx;height:42rpx;border-radius:50%;}.timeline-step.complete .timeline-dot{background:#167b54;color:white;}.rejection-card{background:#fff0ef;border-radius:24rpx;color:#974d49;padding:28rpx;}.process-note{background:#fff4df;border-radius:20rpx;padding:22rpx;}.section-title{font-size:29rpx;}
</style>
